              api.setLanguage(languageCodeArg)
              listOf(null)
            } catch (exception: Throwable) {
              SecurityApiPigeonUtils.wrapError(exception)
            }
            reply.reply(wrapped)
          }
        } else {
          channel.setMessageHandler(null)
        }
      }
    }
  }
}
